 * RFC 3986 URI reference parsing, normalization and resolution.
 */

/** Thrown when a `%XX` percent-encoding is missing one or both hex digits. */
export class TruncatedPercentEncodingError extends Error {
  constructor(component) {
    super(`the ${component} has a truncated percent-encoding`)
    this.component = component
  }
}

const DEFAULT_PORTS = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

/**
 * Split a URI reference into its five generic components. An absent
 * component is `undefined`; the path is always a string, possibly empty.
 */
export function parseUriReference(str) {
  let fragment
  let rest
  const hashIdx = str.indexOf('#')
  if (hashIdx === -1) {
    fragment = undefined
    rest = str
  } else {
    fragment = str.slice(hashIdx + 1)
    rest = str.slice(0, hashIdx)
  }

  let query
  let rest2
  const qIdx = rest.indexOf('?')
  if (qIdx === -1) {
    query = undefined
    rest2 = rest
  } else {
    query = rest.slice(qIdx + 1)
    rest2 = rest.slice(0, qIdx)
  }

  let scheme
  let remainder
  const colonIdx = rest2.indexOf(':')
  const slashIdx = rest2.indexOf('/')
  if (colonIdx !== -1 && (slashIdx === -1 || colonIdx < slashIdx)) {
    scheme = rest2.slice(0, colonIdx)
    remainder = rest2.slice(colonIdx + 1)
  } else {
    scheme = undefined
    remainder = rest2
  }

  let authority
  let path
  if (remainder.startsWith('//')) {
    const afterSlashes = remainder.slice(2)
    const nextSlash = afterSlashes.indexOf('/')
    if (nextSlash === -1) {
      authority = afterSlashes
      path = ''
    } else {
      authority = afterSlashes.slice(0, nextSlash)
      path = afterSlashes.slice(nextSlash)
    }
  } else {
    authority = undefined
    path = remainder
  }

  return { scheme, authority, path, query, fragment }
}

/** Split an authority string into userinfo, host and port. */
function parseAuthority(authority) {
  let userinfo
  let hostport = authority
  const atIdx = authority.lastIndexOf('@')
  if (atIdx === -1) {
    userinfo = undefined
  } else {
    userinfo = authority.slice(0, atIdx)
    hostport = authority.slice(atIdx + 1)
  }

  const bracketIdx = hostport.lastIndexOf(']')
  const searchFrom = bracketIdx === -1 ? 0 : bracketIdx
  const colonIdx = hostport.indexOf(':', searchFrom)
  let host
  let port
  if (colonIdx === -1) {
    host = hostport
    port = undefined
  } else {
    host = hostport.slice(0, colonIdx)
    port = hostport.slice(colonIdx + 1)
  }

  return { userinfo, host, port }
}

function serializeAuthority({ userinfo, host, port }) {
  let s = ''
  if (userinfo !== undefined) s += userinfo + '@'
  s += host
  if (port !== undefined) s += ':' + port
  return s
}

/** Render the five generic components back into a URI reference string. */
export function serializeUriReference({ scheme, authority, path, query, fragment }) {
  let s = ''
  if (scheme !== undefined) s += scheme + ':'
  if (authority !== undefined) s += '//' + authority
  s += path
  if (query !== undefined) s += '?' + query
  if (fragment !== undefined) s += '#' + fragment
  return s
}

function isAsciiUpper(ch) {
  return ch >= 'A' && ch <= 'Z'
}

/** Lowercase only ASCII letters, leaving every other character untouched. */
function asciiLower(str) {
  let out = ''
  for (const ch of str) out += isAsciiUpper(ch) ? ch.toLowerCase() : ch
  return out
}

function isHexDigit(ch) {
  return (ch >= '0' && ch <= '9') || (ch >= 'A' && ch <= 'F') || (ch >= 'a' && ch <= 'f')
}

function isUnreservedByte(code) {
