      throw new TruncatedPercentEncodingError(component)
    }
    const upper = digits.toUpperCase()
    const code = parseInt(upper, 16)
    out += isUnreservedByte(code) ? String.fromCharCode(code) : '%' + upper
    i += 2
  }
  return out
