    const idx = output.lastIndexOf('/')
    output = idx === -1 ? '' : output.slice(0, idx)
  }

  while (input.length > 0) {
    if (input.startsWith('../')) {
      input = input.slice(3)
    } else if (input.startsWith('./')) {
      input = input.slice(2)
    } else if (input.startsWith('/./')) {
      input = '/' + input.slice(3)
    } else if (input === '/.') {
      input = '/'
    } else if (input.startsWith('/../')) {
      input = '/' + input.slice(4)
      dropLastSegment()
    } else if (input === '/..') {
      input = '/'
      dropLastSegment()
    } else if (input === '.' || input === '..') {
      input = ''
    } else {
      const start = input[0] === '/' ? 1 : 0
      let nextSlash = input.indexOf('/', start)
      if (nextSlash === -1) nextSlash = input.length
      output += input.slice(0, nextSlash)
      input = input.slice(nextSlash)
    }
