  let userinfo
  let host
  let port
  if (authority !== undefined) ({ userinfo, host, port } = parseAuthority(authority))

  // Validate every percent-encoding before changing anything, in the order
  // the specification's error messages are checked.
  normalizePercentEncoding(path, 'path')
  if (userinfo !== undefined) normalizePercentEncoding(userinfo, 'userinfo')
  if (host !== undefined) normalizePercentEncoding(host, 'host')
  if (query !== undefined) normalizePercentEncoding(query, 'query')
  if (fragment !== undefined) normalizePercentEncoding(fragment, 'fragment')

  if (scheme !== undefined) scheme = asciiLower(scheme)

  path = normalizePercentEncoding(path, 'path')
  if (userinfo !== undefined) userinfo = normalizePercentEncoding(userinfo, 'userinfo')
  if (host !== undefined) host = normalizePercentEncoding(host, 'host')
  if (query !== undefined) query = normalizePercentEncoding(query, 'query')
  if (fragment !== undefined) fragment = normalizePercentEncoding(fragment, 'fragment')

  if (host !== undefined) host = asciiLower(host)

  if (port !== undefined) {
    const defaultPort = scheme !== undefined ? DEFAULT_PORTS[scheme] : undefined
    if (port === '' || port === defaultPort) port = undefined
  }

  path = removeDotSegments(path)

  if (authority !== undefined && path === '') path = '/'

  const newAuthority = authority !== undefined ? serializeAuthority({ userinfo, host, port }) : undefined

  return serializeUriReference({ scheme, authority: newAuthority, path, query, fragment })
}

/** Normalize a URI reference given as a string. */
export function normalize(str) {
  return normalizeParsed(parseUriReference(str))
}

function mergePaths(base, refPath) {
  if (base.authority !== undefined && base.path === '') return '/' + refPath
  const idx = base.path.lastIndexOf('/')
  if (idx === -1) return refPath
  return base.path.slice(0, idx + 1) + refPath
}

/**
 * Resolve `ref` against `base` (both parsed generic components) by RFC 3986
 * section 5.2.2, strict form, and return the normalized result.
 */
export function resolveParsed(base, ref) {
  let target
  if (ref.scheme !== undefined) {
    target = { scheme: ref.scheme, authority: ref.authority, path: ref.path, query: ref.query, fragment: ref.fragment }
  } else if (ref.authority !== undefined) {
    target = { scheme: base.scheme, authority: ref.authority, path: ref.path, query: ref.query, fragment: ref.fragment }
