{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260923T221316Z/cell-24pqmb/src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js normalize` normalizes one URI reference per
 * input line; `node src/cli.js resolve` resolves the reference on each line
 * against the base that precedes it. Both print one result per line.
 */

import { parseUriReference, normalizeParsed, resolveParsed, TruncatedPercentEncodingError } from './uri.js'

function readStdin() {
  const chunks = []
  process.stdin.setEncoding('utf8')
  return new Promise((resolve, reject) => {
    process.stdin.on('data', (chunk) => chunks.push(chunk))
    process.stdin.on('end', () => resolve(chunks.join('')))
    process.stdin.on('error', reject)
  })
}

function splitRecords(input) {
  if (input === '') return []
  const lines = input.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  return lines
}

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

async function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'normalize' && mode !== 'resolve')) {
    fail('usage: cli.js normalize|resolve')
  }

  const input = await readStdin()
  const records = splitRecords(input)
  const results = []

  for (let i = 0; i < records.length; i++) {
    const lineNumber = i + 1
    const record = records[i]
    try {
      if (mode === 'normalize') {
        results.push(normalizeParsed(parseUriReference(record)))
      } else {
        const spaceIdx = record.indexOf(' ')
        if (spaceIdx === -1) fail(`line ${lineNumber}: expected a base and a reference`)
        const baseStr = record.slice(0, spaceIdx)
        const refStr = record.slice(spaceIdx + 1)
        const base = parseUriReference(baseStr)
        if (base.scheme === undefined) fail(`line ${lineNumber}: the base has no scheme`)
        const ref = parseUriReference(refStr)
        results.push(resolveParsed(base, ref))
      }
    } catch (err) {
      if (err instanceof TruncatedPercentEncodingError) fail(`line ${lineNumber}: ${err.message}`)
      throw err
    }
  }

  process.stdout.write(results.map((line) => line + '\n').join(''))
  process.exit(0)
}

main()
"}

