{"file_path":"src/format.js","content":"/**
 * Renders the resolved regions of a merge into the output for each mode.
 */

/**
 * Renders regions as merged text. Conflicts are written as conflict-marker
 * blocks; `withBase` controls whether the `|||||||` base section is
 * included (true for `merge`, false for `merge2`). Returns the output lines
 * and whether any conflict was written.
 */
export function formatMerge(regions, withBase) {
  const lines = []
  let conflict = false

  for (const region of regions) {
    if (region.kind === 'conflict') {
      conflict = true
      lines.push('<<<<<<< mine', ...region.mineLines)
      if (withBase) lines.push('||||||| base', ...region.baseLines)
      lines.push('=======', ...region.theirsLines, '>>>>>>> theirs')
    } else {
      lines.push(...region.lines)
    }
  }

  return { lines, conflict }
}

/**
 * Renders regions as the `regions` mode's one-line-per-region summary.
 * Returns the output lines and whether any conflict was written.
 */
export function formatRegions(regions) {
  const lines = []
  let conflict = false

  for (const region of regions) {
    if (region.kind === 'conflict') {
      conflict = true
      lines.push(`conflict mine=${region.mineLines.length} base=${region.baseLines.length} theirs=${region.theirsLines.length}`)
    } else {
      lines.push(`${region.kind} ${region.lines.length}`)
    }
  }

  return { lines, conflict }
}
"}

