{"file_path":"./src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */

import fs from 'node:fs'
import { parseInput, ParseError, UnknownTaskError } from './parse.js'
import { findCycle } from './graph.js'
import { computeTimes, pack } from './schedule.js'

const USAGE = 'error: usage: cli.js waves|explain|pack <workers>\n'
const WORKERS_PATTERN = /^[1-9][0-9]*$/

function fail(message, code) {
  process.stderr.write(message)
  process.exit(code)
}

function parseArgs(argv) {
  if (argv.length === 1 && (argv[0] === 'waves' || argv[0] === 'explain')) {
    return { mode: argv[0], workers: null }
  }
  if (argv.length === 2 && argv[0] === 'pack') {
    if (!WORKERS_PATTERN.test(argv[1])) fail('error: workers must be a positive integer\n', 2)
    return { mode: 'pack', workers: parseInt(argv[1], 10) }
  }
  fail(USAGE, 2)
}

const { mode, workers } = parseArgs(process.argv.slice(2))
const input = fs.readFileSync(0, 'utf8')

let tasks
let deps
try {
  ;({ tasks, deps } = parseInput(input))
} catch (err) {
  if (err instanceof ParseError) fail(`error: line ${err.line}: ${err.message}\n`, 2)
  if (err instanceof UnknownTaskError) fail(`error: unknown task ${err.name_}\n`, 2)
  throw err
}

const cycle = findCycle(tasks, deps)
if (cycle) fail(`error: cycle: ${cycle.join(' -> ')}\n`, 3)

if (mode === 'pack') {
  const { workerLog, makespan } = pack(tasks, deps, workers)
  const lines = []
  for (let i = 0; i < workers; i++) {
    const entries = workerLog[i].map((task) => ` ${task.name}@${task.start}-${task.finish}`).join('')
    lines.push(`worker ${i}:${entries}`)
  }
  lines.push(`makespan ${makespan}`)
  process.stdout.write(lines.join('\n') + '\n')
} else {
  const times = computeTimes(tasks, deps)
  const names = [...tasks.keys()].sort()
  let total = 0
  for (const { finish } of times.values()) {
    if (finish > total) total = finish
  }

  const lines = []
  if (mode === 'waves') {
    const waves = new Map()
    for (const name of names) {
      const depth = times.get(name).depth
      if (!waves.has(depth)) waves.set(depth, [])
      waves.get(depth).push(name)
    }
    const maxDepth = waves.size ? Math.max(...waves.keys()) : -1
    for (let depth = 0; depth <= maxDepth; depth++) {
      const waveNames = (waves.get(depth) || []).slice().sort()
      lines.push(`wave ${depth}: ${waveNames.join(' ')}`)
    }
  } else {
    for (const name of names) {
      const { start, finish, depth } = times.get(name)
      lines.push(`${name} start=${start} finish=${finish} depth=${depth}`)
    }
  }
  lines.push(`total ${total}`)
  process.stdout.write(lines.join('\n') + '\n')
}
"}

