{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260923T221316Z/cell-TD1Be8/src/formula.js","content":"/**
 * Tokenizer and recursive-descent parser for a formula body (the text after
 * the leading `=`). Produces an AST, or null when the text isn't in the
 * grammar -- callers turn a null AST into `#ERR!`.
 */

const COMPARISON_OPS = ['=', '<>', '<', '<=', '>', '>=']

/** Splits a formula body into tokens, or returns null on an unknown character. */
function tokenize(str) {
  const tokens = []
  let i = 0
  while (i < str.length) {
    const c = str[i]
    if (c === ' ' || c === '\t') {
      i++
      continue
    }
    if (/[0-9]/.test(c)) {
      let j = i + 1
      while (j < str.length && /[0-9]/.test(str[j])) j++
      if (str[j] === '.' && /[0-9]/.test(str[j + 1] ?? '')) {
        let m = j + 1
        while (m < str.length && /[0-9]/.test(str[m])) m++
        tokens.push({ type: 'NUM', value: str.slice(i, m) })
        i = m
        continue
      }
      tokens.push({ type: 'NUM', value: str.slice(i, j) })
      i = j
      continue
    }
    if (/[A-Za-z]/.test(c)) {
      let j = i + 1
      while (j < str.length && /[A-Za-z]/.test(str[j])) j++
      while (j < str.length && /[0-9]/.test(str[j])) j++
      tokens.push({ type: 'WORD', value: str.slice(i, j) })
      i = j
      continue
    }
    if (c === '<') {
      if (str[i + 1] === '=') {
        tokens.push({ type: 'OP', value: '<=' })
        i += 2
      } else if (str[i + 1] === '>') {
        tokens.push({ type: 'OP', value: '<>' })
        i += 2
      } else {
        tokens.push({ type: 'OP', value: '<' })
        i++
      }
      continue
    }
    if (c === '>') {
      if (str[i + 1] === '=') {
        tokens.push({ type: 'OP', value: '>=' })
        i += 2
      } else {
        tokens.push({ type: 'OP', value: '>' })
        i++
      }
      continue
    }
    if ('^*/+-='.includes(c)) {
      tokens.push({ type: 'OP', value: c })
      i++
      continue
    }
    if (c === '(') {
      tokens.push({ type: 'LPAREN' })
      i++
      continue
    }
    if (c === ')') {
      tokens.push({ type: 'RPAREN' })
      i++
      continue
    }
    if (c === ',') {
      tokens.push({ type: 'COMMA' })
      i++
      continue
    }
    if (c === ':') {
      tokens.push({ type: 'COLON' })
      i++
      continue
    }
    return null
  }
  return tokens
}

class ParseError extends Error {}

class Parser {
  constructor(tokens) {
    this.tokens = tokens
    this.pos = 0
  }

  cur() {
    return this.tokens[this.pos]
  }

  peek(offset) {
    return this.tokens[this.pos + offset]
  }

  advance() {
    return this.tokens[this.pos++]
  }

  atEnd() {
    return this.pos >= this.tokens.length
  }

  expect(type) {
    const t = this.cur()
    if (!t || t.type !== type) throw new ParseError('expected ' + type)
    return this.advance()
  }

  parseFull() {
    const e = this.parseExpr()
    if (!this.atEnd()) throw new ParseError('trailing tokens')
    return e
  }

  parseExpr() {
    return this.parseComparison()
  }

  parseComparison() {
    let left = this.parseAdditive()
    while (!this.atEnd() && this.cur().type === 'OP' && COMPARISON_OPS.includes(this.cur().value)) {
      const op = this.advance().value
      const right = this.parseAdditive()
      left = { type: 'binop', op, left, right }
    }
    return left
  }

  parseAdditive() {
    let left = this.parseMultiplicative()
    while (!this.atEnd() && this.cur().type === 'OP' && (this.cur().value === '+' || this.cur().value === '-')) {
      const op = this.advance().value
      const right = this.parseMultiplicative()
      left = { type: 'binop', op, left, right }
    }
    return left
  }

  parseMultiplicative() {
    let left = this.parsePower()
    while (!this.atEnd() && this.cur().type === 'OP' && (this.cur().value === '*' || this.cur().value === '/')) {
      const op = this.advance().value
      const right = this.parsePower()
      left = { type: 'binop', op, left, right }
    }
    return left
  }

  // A leading sign binds tighter than `^`, so it lives inside parseUnary,
  // which parsePower calls for its left operand before looking for `^`.
  parsePower() {
    const left = this.parseUnary()
    if (!this.atEnd() && this.cur().type === 'OP' && this.cur().value === '^') {
      this.advance()
      const right = this.parsePower()
      return { type: 'binop', op: '^', left, right }
    }
    return left
  }

  parseUnary() {
    if (!this.atEnd() && this.cur().type === 'OP' && (this.cur().value === '-' || this.cur().value === '+')) {
      const op = this.advance().value
      const operand = this.parseUnary()
      return { type: 'unary', op, operand }
    }
    return this.parsePrimary()
  }

  parsePrimary() {
    const t = this.cur()
    if (!t) throw new ParseError('unexpected end')
    if (t.type === 'NUM') {
      this.advance()
      return { type: 'num', value: Number(t.value) }
    }
    if (t.type === 'WORD') {
      this.advance()
      const upper = t.value.toUpperCase()
      if (!this.atEnd() && this.cur().type === 'LPAREN') {
        this.advance()
        const args = this.parseArgs()
        this.expect('RPAREN')
        return { type: 'call', name: upper, args }
      }
      if (upper === 'TRUE') return { type: 'bool', value: true }
      if (upper === 'FALSE') return { type: 'bool', value: false }
      return { type: 'address', name: upper }
    }
    if (t.type === 'LPAREN') {
      this.advance()
      const e = this.parseExpr()
      this.expect('RPAREN')
