 * Evaluation of a parsed formula (or literal) against a sheet, and the
 * companion walk that lists the cells a formula names directly (for
 * `deps` mode) without evaluating anything.
 */

import { parseAddress, expandRange, compareAddresses } from './address.js'
import { parseFormula } from './formula.js'
import { num, text, bool, err, asNumber, compareValues, ERROR_TOKENS } from './values.js'

const LITERAL_NUMBER_RE = /^-?\d+(\.\d+)?$/

/** Reads a non-formula cell's raw content as a value. */
export function parseLiteral(content) {
  if (content === '') return num(0)
  if (LITERAL_NUMBER_RE.test(content)) return num(Number(content))
  if (ERROR_TOKENS.includes(content)) return err(content)
  return text(content)
}

/** Parses a cell's raw content once, caching the result on the record. */
function getParsed(rec) {
  if (rec.parsed) return rec.parsed
  let parsed
  if (rec.content.startsWith('=')) {
    parsed = { kind: 'formula', ast: parseFormula(rec.content.slice(1)) }
  } else {
    parsed = { kind: 'literal', value: parseLiteral(rec.content) }
  }
  rec.parsed = parsed
  return parsed
}

/**
 * Evaluates the cell at a canonical address, memoizing across the whole
 * sheet and detecting cycles via a stack of addresses under evaluation.
 * An address still on the stack yields `#CYCLE!` for that reference; the
 * cells actually on the cycle end up `#CYCLE!` themselves once the error
 * propagates back through their own formulas.
 */
export function evalCell(addr, ctx) {
  if (ctx.memo.has(addr)) return ctx.memo.get(addr)
  if (ctx.stack.has(addr)) return err('#CYCLE!')
  const rec = ctx.sheet.get(addr)
  if (!rec) {
    const v = num(0)
    ctx.memo.set(addr, v)
    return v
  }
  ctx.stack.add(addr)
  const parsed = getParsed(rec)
  const value = parsed.kind === 'literal' ? parsed.value : parsed.ast ? evalNode(parsed.ast, ctx) : err('#ERR!')
  ctx.stack.delete(addr)
  ctx.memo.set(addr, value)
  return value
}

function evalAddressNode(node) {
  const info = parseAddress(node.name)
  return info
}

function evalNode(node, ctx) {
  switch (node.type) {
    case 'num':
      return num(node.value)
    case 'bool':
      return bool(node.value)
    case 'address': {
      const info = evalAddressNode(node)
      if (!info) return err('#REF!')
      return evalCell(info.canonical, ctx)
    }
    case 'unary':
      return applyUnary(node.op, evalNode(node.operand, ctx))
    case 'binop':
      return applyBinop(node.op, evalNode(node.left, ctx), evalNode(node.right, ctx))
    case 'call':
      return evalCall(node, ctx)
    default:
      throw new Error('unreachable node type ' + node.type)
  }
}

function applyUnary(op, v) {
  if (v.k === 'err') return v
  const n = asNumber(v)
  if (n.err) return n.err
  const result = op === '-' ? -n.num : n.num
  return Number.isFinite(result) ? num(result) : err('#DIV/0!')
}

const COMPARISON_OPS = new Set(['=', '<>', '<', '<=', '>', '>='])

function applyBinop(op, l, r) {
  if (COMPARISON_OPS.has(op)) {
    if (l.k === 'err') return l
    if (r.k === 'err') return r
    const c = compareValues(l, r)
    switch (op) {
      case '=':
        return bool(c === 0)
      case '<>':
        return bool(c !== 0)
      case '<':
        return bool(c < 0)
      case '<=':
        return bool(c <= 0)
      case '>':
        return bool(c > 0)
      case '>=':
        return bool(c >= 0)
    }
  }
  // Arithmetic: the left operand's error -- including a text-to-number
  // conversion failure -- wins over the right one's.
  if (l.k === 'err') return l
  const ln = asNumber(l)
  if (ln.err) return ln.err
  if (r.k === 'err') return r
  const rn = asNumber(r)
  if (rn.err) return rn.err
  let result
  switch (op) {
    case '+':
      result = ln.num + rn.num
      break
    case '-':
      result = ln.num - rn.num
      break
    case '*':
      result = ln.num * rn.num
      break
    case '/':
      if (rn.num === 0) return err('#DIV/0!')
      result = ln.num / rn.num
      break
    case '^':
      result = Math.pow(ln.num, rn.num)
      break
    default:
      throw new Error('unreachable op ' + op)
  }
  return Number.isFinite(result) ? num(result) : err('#DIV/0!')
}

/** Flattens one argument node to its list of contributed values, in order. */
function evalArgument(argNode, ctx) {
  if (argNode.type === 'range') {
    const cells = expandRange(argNode.from, argNode.to)
    if (!cells) return [err('#REF!')]
    return cells.map((c) => evalCell(c, ctx))
  }
  return [evalNode(argNode, ctx)]
}

function toCondition(v) {
  if (v.k === 'err') return { err: v }
  if (v.k === 'bool') return { bool: v.v }
  if (v.k === 'num') return { bool: v.v !== 0 }
  return { err: err('#VALUE!') }
}

const AGGREGATE_NAMES = new Set(['SUM', 'MIN', 'MAX', 'COUNT', 'AVG'])

function evalCall(node, ctx) {
  const { name, args } = node
  if (name === 'IF') {
    if (args.length !== 3) return err('#ERR!')
    const condVals = evalArgument(args[0], ctx)
    const condErr = condVals.find((v) => v.k === 'err')
    if (condErr) return condErr
    const cond = toCondition(condVals[0])
    if (cond.err) return cond.err
    const branch = cond.bool ? args[1] : args[2]
    // Only the taken branch is evaluated, so an error (or cycle) in the
    // branch not taken is invisible.
    const vals = evalArgument(branch, ctx)
    return vals[0]
  }
  if (name === 'ABS') {
    if (args.length !== 1) return err('#ERR!')
    const vals = evalArgument(args[0], ctx)
    const firstErr = vals.find((v) => v.k === 'err')
    if (firstErr) return firstErr
    const n = asNumber(vals[0])
    if (n.err) return n.err
    return num(Math.abs(n.num))
  }
  if (!AGGREGATE_NAMES.has(name)) return err('#NAME?')
  if (args.length < 1) return err('#ERR!')
  const allVals = []
  for (const a of args) allVals.push(...evalArgument(a, ctx))
  if (name === 'COUNT') {
    let count = 0
    for (const v of allVals) {
      if (v.k === 'err') return v
      if (v.k === 'num') count++
    }
    return num(count)
  }
  const nums = []
  for (const v of allVals) {
    if (v.k === 'err') return v
    const n = asNumber(v)
    if (n.err) return n.err
    nums.push(n.num)
  }
  let result
  switch (name) {
    case 'SUM':
      result = nums.reduce((s, x) => s + x, 0)
      break
    case 'AVG':
      result = nums.reduce((s, x) => s + x, 0) / nums.length
      break
    case 'MIN':
      result = Math.min(...nums)
      break
    case 'MAX':
      result = Math.max(...nums)
      break
  }
  return Number.isFinite(result) ? num(result) : err('#DIV/0!')
}

/** Collects every cell a parsed formula names directly, ranges expanded. */
export function collectDeps(ast) {
  const set = new Set()
  walk(ast)
  return [...set].sort(compareAddresses)

  function walk(node) {
    switch (node.type) {
      case 'num':
      case 'bool':
        return
      case 'address': {
        const info = parseAddress(node.name)
        if (info) set.add(info.canonical)
        return
      }
      case 'unary':
        walk(node.operand)
        return
      case 'binop':
        walk(node.left)
        walk(node.right)
        return
      case 'call':
        for (const a of node.args) walkArgument(a)
        return
      default:
        throw new Error('unreachable node type ' + node.type)
    }
  }

  function walkArgument(argNode) {
    if (argNode.type === 'range') {
      const cells = expandRange(argNode.from, argNode.to)
      if (cells) for (const c of cells) set.add(c)
      return
    }
    walk(argNode)
  }
}

export { getParsed }
"}

