 * The value nodes a parsed document is built from. Every node has a
 * `type` of `table`, `array-of-tables`, `array`, `string`, `integer`,
 * `float` or `boolean`; tables carry their entries in a `Map` keyed by
 * decoded name text, and array-like nodes carry their elements in
 * `items`. Integers are kept as `BigInt` so arbitrarily large literals
 * round-trip exactly; floats are kept as `Number` since the format
 * prints them the way JSON prints a `Number`.
 */

export function makeTable() {
  return { type: 'table', map: new Map(), headerDefined: false }
}

export function makeArrayOfTables(firstTable) {
  return { type: 'array-of-tables', items: [firstTable] }
}
