 * A hand-written scanner for the token language described in the task: it
 * turns UTF-8 source text into a flat list of tokens, tracking 1-based line
 * and column positions (with 4-column tab stops) as it goes, or throws a
 * ScanError naming the first place the input does not scan.
 */

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])

const TWO_CHAR_PUNCT = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>']
const ONE_CHAR_PUNCT = ['+', '-', '*', '/', '%', '=', '<', '>', '!', '(', ')', '{', '}', '[', ']', ',', ';', '.']

export class ScanError extends Error {
  constructor(line, col, message) {
    super(message)
    this.line = line
    this.col = col
  }
}

class Scanner {
  constructor(source) {
    this.s = source
    this.i = 0
    this.line = 1
    this.col = 1
  }

  atEnd() {
    return this.i >= this.s.length
  }

  // Looks at the UTF-16 code unit `offset` positions ahead without consuming
  // it. Every character this is compared against (punctuation, digits,
  // quotes, comment markers) is ASCII, so code-unit indexing is safe here.
  peekChar(offset = 0) {
    const idx = this.i + offset
    if (idx >= this.s.length) return null
    return this.s[idx]
  }

  // Consumes and returns the next full code point (as a one- or two-unit
  // string), updating line/column per the task's tab-stop and newline rules.
  advance() {
    const cp = this.s.codePointAt(this.i)
    const len = cp > 0xffff ? 2 : 1
    const ch = this.s.slice(this.i, this.i + len)
    this.i += len
    if (cp === 0x0a) {
      this.line += 1
      this.col = 1
    } else if (cp === 0x09) {
      this.col = (Math.floor((this.col - 1) / 4) + 1) * 4 + 1
    } else {
      this.col += 1
    }
    return ch
  }
}

const isDecimalDigit = (c) => c !== null && c >= '0' && c <= '9'
const isHexDigit = (c) => c !== null && /[0-9a-fA-F]/.test(c)
const isBinDigit = (c) => c === '0' || c === '1'
const isOctDigit = (c) => c !== null && c >= '0' && c <= '7'
const isIdentStart = (c) => c !== null && /[A-Za-z_]/.test(c)
const isIdentPart = (c) => c !== null && /[A-Za-z0-9_]/.test(c)
const isPrefixLetter = (c) => c !== null && /[xXbBoO]/.test(c)

function digitTestForPrefix(letter) {
  switch (letter.toLowerCase()) {
    case 'x':
      return isHexDigit
    case 'b':
      return isBinDigit
    default:
      return isOctDigit
  }
}

// Consumes a run of digits satisfying `isDigit`, allowing a single `_`
// between two digits of that same run, and returns how many digits (not
// counting underscores) were consumed.
function consumeDigitRun(scanner, isDigit) {
  let count = 0
  while (true) {
    const c = scanner.peekChar()
    if (isDigit(c)) {
      scanner.advance()
      count += 1
      continue
    }
    if (c === '_' && count > 0 && isDigit(scanner.peekChar(1))) {
      scanner.advance()
      continue
    }
    break
  }
  return count
}

function consumeTrailingInvalid(scanner) {
  while (isIdentPart(scanner.peekChar())) scanner.advance()
}

function skipWhitespaceAndComments(scanner) {
  while (true) {
    const c = scanner.peekChar()
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') {
      scanner.advance()
      continue
    }
    if (c === '/' && scanner.peekChar(1) === '/') {
      scanner.advance()
      scanner.advance()
      while (scanner.peekChar() !== null && scanner.peekChar() !== '\n') scanner.advance()
      continue
    }
    if (c === '/' && scanner.peekChar(1) === '*') {
      const line = scanner.line
      const col = scanner.col
      scanner.advance()
      scanner.advance()
      let depth = 1
      while (depth > 0) {
        const cc = scanner.peekChar()
        if (cc === null) throw new ScanError(line, col, 'unterminated block comment')
        if (cc === '/' && scanner.peekChar(1) === '*') {
          scanner.advance()
          scanner.advance()
          depth += 1
          continue
        }
        if (cc === '*' && scanner.peekChar(1) === '/') {
          scanner.advance()
          scanner.advance()
          depth -= 1
          continue
        }
        scanner.advance()
      }
      continue
    }
    break
  }
}

function scanIdent(scanner, line, col) {
  const startIndex = scanner.i
  while (isIdentPart(scanner.peekChar())) scanner.advance()
  const text = scanner.s.slice(startIndex, scanner.i)
  return { kind: KEYWORDS.has(text) ? 'keyword' : 'ident', line, col, text }
}

function scanNumber(scanner, line, col) {
  const startIndex = scanner.i
  if (scanner.peekChar() === '0' && isPrefixLetter(scanner.peekChar(1))) {
    scanner.advance() // '0'
    const prefixLetter = scanner.advance() // x/X, b/B or o/O
    const count = consumeDigitRun(scanner, digitTestForPrefix(prefixLetter))
    if (count === 0) {
      consumeTrailingInvalid(scanner)
      throw new ScanError(line, col, `invalid number ${scanner.s.slice(startIndex, scanner.i)}`)
    }
  } else {
    consumeDigitRun(scanner, isDecimalDigit)
    if (scanner.peekChar() === '.' && isDecimalDigit(scanner.peekChar(1))) {
      scanner.advance() // '.'
      consumeDigitRun(scanner, isDecimalDigit)
    }
    if (scanner.peekChar() === 'e' || scanner.peekChar() === 'E') {
      let signOffset = 1
      const hasSign = scanner.peekChar(1) === '+' || scanner.peekChar(1) === '-'
      if (hasSign) signOffset = 2
      if (isDecimalDigit(scanner.peekChar(signOffset))) {
        scanner.advance() // 'e'/'E'
        if (hasSign) scanner.advance() // sign
        consumeDigitRun(scanner, isDecimalDigit)
      }
    }
  }
  if (isIdentPart(scanner.peekChar())) {
    consumeTrailingInvalid(scanner)
    throw new ScanError(line, col, `invalid number ${scanner.s.slice(startIndex, scanner.i)}`)
  }
  return { kind: 'number', line, col, text: scanner.s.slice(startIndex, scanner.i) }
}

function scanString(scanner, line, col) {
  scanner.advance() // opening quote
  let decoded = ''
  while (true) {
    const c = scanner.peekChar()
    if (c === null) throw new ScanError(line, col, 'unterminated string')
    if (c === '"') {
      scanner.advance()
      break
    }
    if (c === '\n') throw new ScanError(scanner.line, scanner.col, 'newline in string')
    if (c === '\\') {
      const escLine = scanner.line
      const escCol = scanner.col
      scanner.advance() // backslash
      const e = scanner.peekChar()
      if (e === null) throw new ScanError(line, col, 'unterminated string')
      if (e === 'n') {
        decoded += '\n'
        scanner.advance()
      } else if (e === 't') {
        decoded += '\t'
        scanner.advance()
      } else if (e === 'r') {
        decoded += '\r'
        scanner.advance()
      } else if (e === '\\') {
        decoded += '\\'
        scanner.advance()
      } else if (e === '"') {
        decoded += '"'
        scanner.advance()
      } else if (e === '0') {
        decoded += '\0'
        scanner.advance()
      } else if (e === 'x') {
        scanner.advance() // 'x'
        const h1 = scanner.peekChar()
        if (h1 === null) throw new ScanError(line, col, 'unterminated string')
        if (!isHexDigit(h1)) throw new ScanError(escLine, escCol, 'invalid escape \\x')
        scanner.advance()
        const h2 = scanner.peekChar()
        if (h2 === null) throw new ScanError(line, col, 'unterminated string')
        if (!isHexDigit(h2)) throw new ScanError(escLine, escCol, 'invalid escape \\x')
        scanner.advance()
        decoded += String.fromCharCode(parseInt(h1 + h2, 16))
      } else if (e === 'u') {
        scanner.advance() // 'u'
        const brace = scanner.peekChar()
        if (brace === null) throw new ScanError(line, col, 'unterminated string')
        if (brace !== '{') throw new ScanError(escLine, escCol, 'invalid escape \\u')
        scanner.advance() // '{'
        let hex = ''
        while (true) {
          const hc = scanner.peekChar()
          if (hc === null) throw new ScanError(line, col, 'unterminated string')
          if (hc === '}') break
          if (!isHexDigit(hc)) throw new ScanError(escLine, escCol, 'invalid escape \\u')
          hex += hc
          scanner.advance()
        }
        scanner.advance() // '}'
        const value = parseInt(hex, 16)
        if (hex.length === 0 || value > 0x10ffff) throw new ScanError(escLine, escCol, 'invalid escape \\u')
        decoded += String.fromCodePoint(value)
      } else {
        throw new ScanError(escLine, escCol, `invalid escape \\${e}`)
      }
      continue
    }
    decoded += scanner.advance()
  }
  return { kind: 'string', line, col, text: JSON.stringify(decoded) }
}

function scanRawString(scanner, line, col) {
  scanner.advance() // 'r'
  scanner.advance() // opening quote
  const startIndex = scanner.i
  while (true) {
    const c = scanner.peekChar()
    if (c === null) throw new ScanError(line, col, 'unterminated string')
    if (c === '"') break
    scanner.advance()
  }
  const raw = scanner.s.slice(startIndex, scanner.i)
  scanner.advance() // closing quote
  return { kind: 'rawstring', line, col, text: JSON.stringify(raw) }
}

function scanPunct(scanner) {
  const c0 = scanner.peekChar()
  const c1 = scanner.peekChar(1)
  if (c0 !== null && c1 !== null) {
    const two = c0 + c1
    if (TWO_CHAR_PUNCT.includes(two)) {
      scanner.advance()
      scanner.advance()
      return two
    }
  }
  if (c0 !== null && ONE_CHAR_PUNCT.includes(c0)) {
    scanner.advance()
    return c0
  }
  return null
}

function scanToken(scanner) {
  const line = scanner.line
  const col = scanner.col
  const c = scanner.peekChar()
  if (isIdentStart(c)) return scanIdent(scanner, line, col)
  if (isDecimalDigit(c)) return scanNumber(scanner, line, col)
  if (c === '"') return scanString(scanner, line, col)
  if (c === 'r' && scanner.peekChar(1) === '"') return scanRawString(scanner, line, col)
  const punct = scanPunct(scanner)
  if (punct !== null) return { kind: 'punct', line, col, text: punct }
  const ch = scanner.advance()
  throw new ScanError(line, col, `unexpected character ${ch}`)
}

export function scan(source) {
  const scanner = new Scanner(source)
  const tokens = []
  while (true) {
    skipWhitespaceAndComments(scanner)
    if (scanner.atEnd()) break
    tokens.push(scanToken(scanner))
  }
  return tokens
}
"}

