{"file_path":"./src/lexer.js","content":"/**
 * Scans UTF-8 source text into a stream of positioned tokens.
 */

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])

const TWO_CHAR_PUNCT = new Set(['==', '!=', '<=', '>=', '&&', '||', '->', '=>'])
const ONE_CHAR_PUNCT = new Set([
  '+', '-', '*', '/', '%', '=', '<', '>', '!', '(', ')', '{', '}', '[', ']', ',', ';', '.',
])

class LexError extends Error {
  constructor(line, col, reason) {
    super(reason)
    this.line = line
    this.col = col
    this.reason = reason
  }
}

function isIdentStart(c) {
  return c !== undefined && /[A-Za-z_]/.test(c)
}

function isIdentContinue(c) {
  return c !== undefined && /[A-Za-z0-9_]/.test(c)
}

function isDecimalDigit(c) {
  return c !== undefined && c >= '0' && c <= '9'
}

function isHexDigit(c) {
  return c !== undefined && /[0-9a-fA-F]/.test(c)
}

function isBinaryDigit(c) {
  return c === '0' || c === '1'
}

function isOctalDigit(c) {
  return c !== undefined && c >= '0' && c <= '7'
}

function isTrailingInvalid(c) {
  return c !== undefined && /[A-Za-z0-9_]/.test(c)
}

class Lexer {
  constructor(text) {
    this.chars = Array.from(text)
    this.idx = 0
    this.line = 1
    this.col = 1
  }

  atEnd(offset = 0) {
    return this.idx + offset >= this.chars.length
  }

  peek(offset = 0) {
    return this.chars[this.idx + offset]
  }

  advance() {
    const c = this.chars[this.idx]
    this.idx++
    if (c === '\n') {
      this.line++
      this.col = 1
    } else if (c === '\t') {
      this.col = this.col + (4 - ((this.col - 1) % 4))
    } else {
      this.col++
    }
    return c
  }

  error(line, col, reason) {
    return new LexError(line, col, reason)
  }

  skipWhitespace() {
    while (!this.atEnd()) {
      const c = this.peek()
      if (c === ' ' || c === '\t' || c === '\r' || c === '\n') {
        this.advance()
      } else {
        break
      }
    }
  }

  skipLineComment() {
    this.advance() // /
    this.advance() // /
    while (!this.atEnd() && this.peek() !== '\n') {
      this.advance()
    }
  }

  skipBlockComment() {
    const startLine = this.line
    const startCol = this.col
    this.advance() // /
    this.advance() // *
    let depth = 1
    while (depth > 0) {
      if (this.atEnd()) {
        throw this.error(startLine, startCol, 'unterminated block comment')
      }
      if (this.peek() === '/' && this.peek(1) === '*') {
        this.advance()
        this.advance()
        depth++
        continue
      }
      if (this.peek() === '*' && this.peek(1) === '/') {
        this.advance()
        this.advance()
        depth--
        continue
      }
      this.advance()
    }
  }

  scanDigitRun(isDigit) {
    let count = 0
    while (true) {
      const c = this.peek()
      if (isDigit(c)) {
        this.advance()
        count++
        continue
      }
      if (c === '_' && count > 0 && isDigit(this.peek(1))) {
        this.advance()
        continue
      }
      break
    }
    return count
  }

  scanNumber(startLine, startCol) {
    const startIdx = this.idx
    let sawDigit = true

    if (this.peek() === '0' && /[xXbBoO]/.test(this.peek(1) ?? '')) {
      const prefixChar = this.peek(1).toLowerCase()
      this.advance() // 0
      this.advance() // x/b/o
      const isDigit = prefixChar === 'x' ? isHexDigit : prefixChar === 'b' ? isBinaryDigit : isOctalDigit
      const digits = this.scanDigitRun(isDigit)
      sawDigit = digits > 0
    } else {
      this.scanDigitRun(isDecimalDigit)
      if (this.peek() === '.' && isDecimalDigit(this.peek(1))) {
        this.advance() // .
        this.scanDigitRun(isDecimalDigit)
      }
      if (this.peek() === 'e' || this.peek() === 'E') {
        if (isDecimalDigit(this.peek(1))) {
          this.advance() // e
          this.scanDigitRun(isDecimalDigit)
        } else if ((this.peek(1) === '+' || this.peek(1) === '-') && isDecimalDigit(this.peek(2))) {
          this.advance() // e
          this.advance() // sign
          this.scanDigitRun(isDecimalDigit)
        }
      }
    }

    if (isTrailingInvalid(this.peek())) {
      this.advance()
      const text = this.chars.slice(startIdx, this.idx).join('')
      throw this.error(startLine, startCol, `invalid number ${text}`)
    }

    if (!sawDigit) {
      const text = this.chars.slice(startIdx, this.idx).join('')
      throw this.error(startLine, startCol, `invalid number ${text}`)
    }

    const text = this.chars.slice(startIdx, this.idx).join('')
    return { kind: 'number', text, line: startLine, col: startCol }
  }

  scanIdentifier(startLine, startCol) {
    const startIdx = this.idx
    this.advance()
    while (isIdentContinue(this.peek())) {
      this.advance()
    }
    const text = this.chars.slice(startIdx, this.idx).join('')
    const kind = KEYWORDS.has(text) ? 'keyword' : 'ident'
    return { kind, text, line: startLine, col: startCol }
  }

  scanStringBody(startLine, startCol) {
    let value = ''
    while (true) {
      if (this.atEnd()) {
        throw this.error(startLine, startCol, 'unterminated string')
      }
      const c = this.peek()
      if (c === '"') {
        this.advance()
        break
      }
      if (c === '\n') {
        throw this.error(this.line, this.col, 'newline in string')
      }
      if (c === '\\') {
        const bsLine = this.line
        const bsCol = this.col
        this.advance() // backslash
        if (this.atEnd()) {
          throw this.error(startLine, startCol, 'unterminated string')
        }
        const e = this.peek()
        switch (e) {
          case 'n':
            value += '\n'
            this.advance()
            break
          case 't':
            value += '\t'
            this.advance()
            break
          case 'r':
            value += '\r'
            this.advance()
            break
          case '\\':
            value += '\\'
            this.advance()
            break
          case '"':
