 * Computes, for every task, the cost of the longest chain that begins at
 * it: its own cost plus the chain of whichever task depends on it goes
 * furthest, down to a task nothing depends on (which contributes 0).
 */
function computePriorities(tasks, adjacency) {
  const dependents = new Map()
  for (const name of tasks.keys()) dependents.set(name, [])
  for (const [name, deps] of adjacency) {
    for (const dep of deps) dependents.get(dep).push(name)
  }

  const priority = new Map()
  function compute(name) {
    if (priority.has(name)) return priority.get(name)
    let best = 0
    for (const dependent of dependents.get(name)) {
      best = Math.max(best, compute(dependent))
    }
    const value = tasks.get(name) + best
    priority.set(name, value)
    return value
  }

  for (const name of tasks.keys()) compute(name)
  return priority
}

/**
 * Simulates the graph on `workerCount` workers, greedily starting the
 * ready task of greatest priority (ties broken by ascending name) on the
 * free worker of smallest index whenever both are available, and
 * otherwise advancing time to the next moment a worker frees up.
 */
export function packWorkers({ tasks, adjacency }, workerCount) {
  const priority = computePriorities(tasks, adjacency)
  const workers = Array.from({ length: workerCount }, () => ({ busyUntil: 0, log: [] }))
  const finish = new Map()
  const pending = new Set(tasks.keys())

  let time = 0
  while (pending.size > 0) {
    let progressed = true
    while (progressed) {
      progressed = false
      let freeWorker = -1
      for (let i = 0; i < workers.length; i++) {
        if (workers[i].busyUntil <= time) {
          freeWorker = i
          break
        }
      }
      if (freeWorker === -1) break

      let chosen = null
      for (const name of pending) {
        const deps = adjacency.get(name)
        let ready = true
        for (const dep of deps) {
          if (!finish.has(dep) || finish.get(dep) > time) {
            ready = false
            break
          }
        }
        if (!ready) continue
        if (
          chosen === null ||
          priority.get(name) > priority.get(chosen) ||
          (priority.get(name) === priority.get(chosen) && name < chosen)
        ) {
          chosen = name
        }
      }
      if (chosen === null) break

      const taskFinish = time + tasks.get(chosen)
      workers[freeWorker].log.push({ name: chosen, start: time, finish: taskFinish })
      workers[freeWorker].busyUntil = taskFinish
      finish.set(chosen, taskFinish)
      pending.delete(chosen)
      progressed = true
    }

    if (pending.size === 0) break
    let next = Infinity
    for (const worker of workers) {
      if (worker.busyUntil > time) next = Math.min(next, worker.busyUntil)
    }
    time = next
  }

  let makespan = 0
  for (const value of finish.values()) makespan = Math.max(makespan, value)

  return { workers, makespan }
}
"}

