 * Count an election by instant-runoff, one round at a time, and return every
 * round's tally plus the eventual winner.
 *
 * Each returned round has `counts` (a Map from candidate name to vote count,
 * in descending-count/ascending-name display order), `exhausted` (a BigInt),
 * `eliminated` (the name removed after this round, or `null`), and `winner`
 * (the name who won this round, or `null`).
 */
export function runElection(candidates, ballots) {
  const totalBallots = ballots.reduce((sum, b) => sum + b.count, 0n)
  let continuing = new Set(candidates)
  const history = []
  const rounds = []
  let winner = null

  while (true) {
    const counts = new Map()
    for (const c of continuing) counts.set(c, 0n)
    let activeTotal = 0n
    for (const ballot of ballots) {
      const pick = ballot.ranking.find((name) => continuing.has(name))
      if (pick !== undefined) {
        counts.set(pick, counts.get(pick) + ballot.count)
        activeTotal += ballot.count
      }
    }
    history.push(counts)

    let roundWinner = null
    if (activeTotal > 0n) {
      for (const name of continuing) {
        if (counts.get(name) * 2n > activeTotal) {
          roundWinner = name
          break
        }
      }
    }

    let eliminated = null
    if (roundWinner === null && activeTotal > 0n) {
      eliminated = selectElimination(continuing, counts, history)
      continuing.delete(eliminated)
    }

    rounds.push({
      counts: sortedCounts(counts),
      exhausted: totalBallots - activeTotal,
      eliminated,
      winner: roundWinner,
    })

    if (roundWinner !== null || activeTotal === 0n) {
      winner = roundWinner
      break
    }
  }

  return { rounds, winner }
}

function sortedCounts(counts) {
  const entries = [...counts.entries()]
  entries.sort((a, b) => {
    if (a[1] !== b[1]) return a[1] > b[1] ? -1 : 1
    return a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0
  })
  return entries
}

function selectElimination(continuing, counts, history) {
  let minVal = null
  for (const name of continuing) {
    const v = counts.get(name)
    if (minVal === null || v < minVal) minVal = v
  }
  let tied = [...continuing].filter((name) => counts.get(name) === minVal)

  while (tied.length > 1) {
    let separated = false
    for (const roundCounts of history) {
      const values = tied.map((name) => roundCounts.get(name))
      const distinct = new Set(values)
      if (distinct.size > 1) {
        let roundMin = values[0]
        for (const v of values) if (v < roundMin) roundMin = v
        tied = tied.filter((name, i) => values[i] === roundMin)
        separated = true
        break
      }
    }
    if (!separated) break
  }

  if (tied.length === 1) return tied[0]
  return tied.reduce((a, b) => (a > b ? a : b))
}
"}

