{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260923T221316Z/cell-iLlnAc/src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js rounds` prints every round of the instant-runoff
 * count read from standard input, and `node src/cli.js tally` prints only how
 * many rounds ran and who won.
 */

import { readFileSync } from 'node:fs'
import { parseElection } from './parse.js'
import { runElection } from './election.js'
import { ElectionError } from './errors.js'

function usageError() {
  process.stderr.write('error: usage: cli.js rounds|tally\n')
  process.exit(2)
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'rounds' && args[0] !== 'tally')) {
    usageError()
    return
  }
  const mode = args[0]

  let input
  try {
    input = readFileSync(0, 'utf8')
  } catch {
    input = ''
  }

  let candidates, ballots
  try {
    ;({ candidates, ballots } = parseElection(input))
  } catch (error) {
    if (error instanceof ElectionError) {
      const where = error.line === null ? '' : `line ${error.line}: `
      process.stderr.write(`error: ${where}${error.message}\n`)
      process.exit(2)
    }
    throw error
  }

  const { rounds, winner } = runElection(candidates, ballots)

  const output = []
  if (mode === 'rounds') {
    rounds.forEach((round, index) => {
      const parts = round.counts.map(([name, count]) => `${name}=${count}`)
      output.push(`round ${index + 1}: ${parts.join(' ')} exhausted=${round.exhausted}`)
      if (round.eliminated !== null) output.push(`eliminated ${round.eliminated}`)
    })
  } else {
    output.push(`rounds ${rounds.length}`)
  }
  output.push(winner === null ? 'no winner' : `winner ${winner}`)

  process.stdout.write(output.join('\n') + '\n')
}

main()
"}

