 * Parsing of URI references into their generic-syntax components, per RFC
 * 3986's grammar. Each component is `undefined` when the reference omits
 * it, and a string (possibly empty) when the reference writes it.
 */

/**
 * Splits a URI reference into scheme, authority, path, query and fragment.
 * `path` is always a string; the other four may be `undefined`.
 */
export function parseUriRef(ref) {
  let rest = ref
  let scheme

  const schemeBoundary = rest.search(/[:/?#]/)
  if (schemeBoundary !== -1 && rest[schemeBoundary] === ':') {
    scheme = rest.slice(0, schemeBoundary)
    rest = rest.slice(schemeBoundary + 1)
  }

  let authority
  if (rest.startsWith('//')) {
    const remainder = rest.slice(2)
    const authorityEnd = remainder.search(/[/?#]/)
    if (authorityEnd === -1) {
      authority = remainder
      rest = ''
    } else {
      authority = remainder.slice(0, authorityEnd)
      rest = remainder.slice(authorityEnd)
    }
  }

  const pathEnd = rest.search(/[?#]/)
  let path
  if (pathEnd === -1) {
    path = rest
    rest = ''
  } else {
    path = rest.slice(0, pathEnd)
    rest = rest.slice(pathEnd)
  }

  let query
  if (rest.startsWith('?')) {
    const queryEnd = rest.indexOf('#')
    if (queryEnd === -1) {
      query = rest.slice(1)
      rest = ''
    } else {
      query = rest.slice(1, queryEnd)
      rest = rest.slice(queryEnd)
    }
  }

  let fragment
  if (rest.startsWith('#')) {
    fragment = rest.slice(1)
  }

  return { scheme, authority, path, query, fragment }
}

/**
 * Splits an authority into userinfo, host and port. Userinfo is everything
 * before the last `@`; the port is everything after the first `:` that
 * follows the last `]`; the host is what remains between them.
 */
export function parseAuthority(authority) {
  const atIndex = authority.lastIndexOf('@')
  const userinfo = atIndex === -1 ? undefined : authority.slice(0, atIndex)
  const hostPort = atIndex === -1 ? authority : authority.slice(atIndex + 1)

  const bracketIndex = hostPort.lastIndexOf(']')
  const searchFrom = bracketIndex === -1 ? 0 : bracketIndex + 1
  const colonIndex = hostPort.indexOf(':', searchFrom)

  const host = colonIndex === -1 ? hostPort : hostPort.slice(0, colonIndex)
  const port = colonIndex === -1 ? undefined : hostPort.slice(colonIndex + 1)

  return { userinfo, host, port }
}

/** Rebuilds an authority string from its userinfo, host and port parts. */
export function buildAuthority({ userinfo, host, port }) {
  let s = ''
  if (userinfo !== undefined) s += userinfo + '@'
  s += host
  if (port !== undefined) s += ':' + port
  return s
}

/** Rebuilds a URI reference string from its parsed components. */
export function buildUriRef({ scheme, authority, path, query, fragment }) {
  let s = ''
  if (scheme !== undefined) s += scheme + ':'
  if (authority !== undefined) s += '//' + authority
  s += path
  if (query !== undefined) s += '?' + query
  if (fragment !== undefined) s += '#' + fragment
  return s
}
