 * Reference resolution per RFC 3986 section 5.2.2, in its strict form: a
 * reference that repeats the base's scheme is still treated as an absolute
 * URI. The caller is responsible for normalizing the result, including its
 * dot-segment removal.
 */

/**
 * Merges a relative reference path onto a base path per RFC 3986 section
 * 5.2.3.
 */
function mergePaths(base, refPath) {
  if (base.authority !== undefined && base.path === '') {
    return '/' + refPath
  }
  const lastSlash = base.path.lastIndexOf('/')
  if (lastSlash === -1) return refPath
  return base.path.slice(0, lastSlash + 1) + refPath
}

/**
 * Resolves a parsed reference against a parsed base, returning the
 * un-normalized target components. `base` must have a scheme.
 */
export function resolveReference(base, ref) {
  if (ref.scheme !== undefined) {
    return {
      scheme: ref.scheme,
      authority: ref.authority,
      path: ref.path,
      query: ref.query,
      fragment: ref.fragment,
    }
  }

  if (ref.authority !== undefined) {
    return {
      scheme: base.scheme,
      authority: ref.authority,
      path: ref.path,
      query: ref.query,
      fragment: ref.fragment,
    }
  }

  if (ref.path === '') {
    return {
      scheme: base.scheme,
      authority: base.authority,
      path: base.path,
      query: ref.query !== undefined ? ref.query : base.query,
      fragment: ref.fragment,
    }
  }

  return {
    scheme: base.scheme,
    authority: base.authority,
    path: ref.path.startsWith('/') ? ref.path : mergePaths(base, ref.path),
    query: ref.query,
    fragment: ref.fragment,
  }
}
"}

