/**
 * The command. `node src/cli.js normalize` normalizes one URI reference per
 * input line; `node src/cli.js resolve` resolves the reference on each line
 * against the base that precedes it. Both print one result per line.
 */
import { parseUriRef, buildUriRef } from './parse.js'
import { normalize } from './normalize.js'
import { resolveReference } from './resolve.js'
import { UriError } from './errors.js'

function readStdin() {
  const chunks = []
  let chunk
  const fd = 0
  const buf = Buffer.alloc(65536)
  const fs = require('node:fs')
  for (;;) {
    let bytesRead
    try {
      bytesRead = fs.readSync(fd, buf, 0, buf.length, null)
    } catch (err) {
      if (err.code === 'EAGAIN') continue
      if (err.code === 'EOF') break
      throw err
    }
    if (bytesRead === 0) break
    chunks.push(Buffer.from(buf.subarray(0, bytesRead)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

function splitRecords(input) {
  if (input === '') return []
  const lines = input.split('\n')
  if (input.endsWith('\n')) lines.pop()
  return lines
}

function fail(lineNumber, message) {
  process.stderr.write(`error: line ${lineNumber}: ${message}\n`)
  process.exit(2)
}

function runNormalize(records) {
  const results = []
  records.forEach((record, index) => {
    try {
      const parsed = parseUriRef(record)
      results.push(buildUriRef(normalize(parsed)))
    } catch (err) {
      if (err instanceof UriError) fail(index + 1, err.message)
      throw err
    }
  })
  return results
}

function runResolve(records) {
  const results = []
  records.forEach((record, index) => {
    const lineNumber = index + 1
    const spaceIndex = record.indexOf(' ')
    if (spaceIndex === -1) fail(lineNumber, 'expected a base and a reference')

    const baseText = record.slice(0, spaceIndex)
    const refText = record.slice(spaceIndex + 1)

    const base = parseUriRef(baseText)
    if (base.scheme === undefined) fail(lineNumber, 'the base has no scheme')

    try {
      const ref = parseUriRef(refText)
      const target = resolveReference(base, ref)
      results.push(buildUriRef(normalize(target)))
    } catch (err) {
      if (err instanceof UriError) fail(lineNumber, err.message)
      throw err
    }
  })
  return results
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'normalize' && args[0] !== 'resolve')) {
    process.stderr.write('error: usage: cli.js normalize|resolve\n')
    process.exit(2)
  }

  const mode = args[0]
  const input = readStdin()
  const records = splitRecords(input)

  const results = mode === 'normalize' ? runNormalize(records) : runResolve(records)

  process.stdout.write(results.map((line) => line + '\n').join(''))
  process.exit(0)
}

main()
"}

