{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260923T221316Z/cell-ja995b/src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js replay` verdicts every event of the limiter
 * file read from standard input, and `node src/cli.js summary` totals the
 * verdicts per key.
 */
import { simulate } from './simulate.js'
import { LimiterError } from './limiterError.js'

function readStdin() {
  const chunks = []
  const fd = 0
  const buffer = Buffer.alloc(65536)
  const fs = require('node:fs')
  while (true) {
    let bytesRead
    try {
      bytesRead = fs.readSync(fd, buffer, 0, buffer.length, null)
    } catch (err) {
      if (err.code === 'EAGAIN') continue
      if (err.code === 'EOF') break
      throw err
    }
    if (bytesRead === 0) break
    chunks.push(Buffer.from(buffer.subarray(0, bytesRead)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'replay' && mode !== 'summary')) {
    process.stderr.write('error: usage: cli.js replay|summary\n')
    process.exit(2)
  }

  const input = readStdin()

  let result
  try {
    result = simulate(input)
  } catch (err) {
    if (err instanceof LimiterError) {
      process.stderr.write(`error: ${err.message}\n`)
      process.exit(2)
    }
    throw err
  }

  const lines = []
  if (mode === 'replay') {
    for (const event of result.events) {
      if (event.allowed) {
        lines.push(`${event.tick} ${event.key} allow`)
      } else {
        lines.push(`${event.tick} ${event.key} deny ${event.deniedBy}`)
      }
    }
  } else {
    const keys = Array.from(result.summary.keys()).sort()
    let totalAllowed = 0
    let totalDenied = 0
    for (const key of keys) {
      const { allowed, denied } = result.summary.get(key)
      lines.push(`${key} allowed=${allowed} denied=${denied}`)
      totalAllowed += allowed
      totalDenied += denied
    }
    lines.push(`total allowed=${totalAllowed} denied=${totalDenied}`)
  }

  process.stdout.write(lines.length ? lines.join('\n') + '\n' : '')
}

main()
"}

