{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260923T221316Z/cell-kI4doV/src/parser.js","content":"/**
 * Parses the plain-text election format read from standard input: a
 * `candidates` line followed by any number of `ballot` lines, with blank
 * lines and `#` comments ignored.
 */

const NAME_RE = /^[A-Za-z0-9_-]+$/
const COUNT_RE = /^[1-9][0-9]*$/

export class ParseError extends Error {
  constructor(line, message) {
    super(message)
    this.line = line
  }
}

/**
 * Splits raw standard input into election lines, then parses those lines
 * into a candidate list and a set of ballots. Throws a `ParseError` at the
 * first line that violates the format.
 */
export function parseElection(input) {
  const rawLines = input.split('\n')
  if (rawLines.length > 0 && rawLines[rawLines.length - 1] === '') {
    rawLines.pop()
  }

  let candidatesDeclared = false
  let candidates = []
  let candidateSet = new Set()
  const ballots = []

  for (let i = 0; i < rawLines.length; i += 1) {
    const lineNo = i + 1
    const trimmed = rawLines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const tokens = trimmed.split(/\s+/)
    const directive = tokens[0]

    if (directive === 'candidates') {
      if (candidatesDeclared) {
        throw new ParseError(lineNo, 'candidates must be declared once, before any ballot')
      }
      candidatesDeclared = true
      if (tokens.length < 2) {
        throw new ParseError(lineNo, 'expected candidates <name>...')
      }
      const names = tokens.slice(1)
      const set = new Set()
      for (const name of names) {
        if (!NAME_RE.test(name)) {
          throw new ParseError(lineNo, `invalid candidate name ${name}`)
        }
        if (set.has(name)) {
          throw new ParseError(lineNo, `candidate ${name} is declared twice`)
        }
        set.add(name)
      }
      candidates = names
      candidateSet = set
    } else if (directive === 'ballot') {
      if (!candidatesDeclared) {
        throw new ParseError(lineNo, 'candidates must be declared once, before any ballot')
      }
      if (tokens.length < 3) {
        throw new ParseError(lineNo, 'expected ballot <count> <candidate>...')
      }
      const countToken = tokens[1]
      if (!COUNT_RE.test(countToken)) {
        throw new ParseError(lineNo, 'count must be a positive integer')
      }
      const count = Number(countToken)
      const names = tokens.slice(2)
      const used = new Set()
      for (const name of names) {
        if (!candidateSet.has(name)) {
          throw new ParseError(lineNo, `unknown candidate ${name}`)
        }
        if (used.has(name)) {
          throw new ParseError(lineNo, `candidate ${name} is repeated`)
        }
        used.add(name)
      }
      ballots.push({ count, preferences: names })
    } else {
      throw new ParseError(lineNo, `unknown directive ${directive}`)
    }
  }

  if (!candidatesDeclared) {
    throw new ParseError(null, 'no candidates')
  }

  return { candidates, ballots }
}
"}

