{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260923T221316Z/cell-kI4doV/src/election.js","content":"/**
 * Runs an instant-runoff count over a parsed election: repeated rounds of
 * tallying ballots for the most-preferred continuing candidate, eliminating
 * the weakest candidate between rounds, until someone wins a majority of the
 * active vote or every ballot is exhausted.
 */

/**
 * Counts one round: each ballot's count goes to the first candidate on it
 * that is still continuing, or to the exhausted total when none remain.
 */
function tallyRound(ballots, continuing) {
  const counts = new Map()
  for (const name of continuing) counts.set(name, 0)
  let exhausted = 0

  for (const ballot of ballots) {
    const choice = ballot.preferences.find((name) => continuing.has(name))
    if (choice === undefined) {
      exhausted += ballot.count
    } else {
      counts.set(choice, counts.get(choice) + ballot.count)
    }
  }

  return { counts, exhausted }
}

/**
 * Picks which of the tied-for-fewest candidates to eliminate: the one
 * fewest in the earliest round where the tied group's counts first differ,
 * narrowing repeatedly, and falling back to the name that sorts last by
 * code point when no round ever separates them.
 */
function breakElimination(tied, history) {
  let survivors = tied
  for (const roundCounts of history) {
    if (survivors.length === 1) break
    const values = survivors.map((name) => roundCounts.get(name))
    const allEqual = values.every((v) => v === values[0])
    if (allEqual) continue
    const min = Math.min(...values)
    survivors = survivors.filter((name) => roundCounts.get(name) === min)
  }
  if (survivors.length === 1) return survivors[0]
  return survivors.slice().sort().reverse()[0]
}

/**
 * Runs the full instant-runoff count and returns each round's tally plus
 * the eventual winner, or null when no candidate ever reaches a majority.
 */
export function runElection(candidates, ballots) {
  const continuing = new Set(candidates)
  const rounds = []
  const history = []
  let winner = null

  for (;;) {
    const { counts, exhausted } = tallyRound(ballots, continuing)
    history.push(counts)

    const activeTotal = [...counts.values()].reduce((a, b) => a + b, 0)

    let roundWinner = null
    if (activeTotal > 0) {
      for (const name of continuing) {
        if (counts.get(name) * 2 > activeTotal) {
          roundWinner = name
          break
        }
      }
    }

    let eliminated = null
    if (activeTotal === 0) {
      // No ballot counted for anyone; the election ends without a winner.
    } else if (roundWinner !== null) {
      winner = roundWinner
    } else {
      let fewest = Infinity
      for (const name of continuing) {
        if (counts.get(name) < fewest) fewest = counts.get(name)
      }
      const tied = [...continuing].filter((name) => counts.get(name) === fewest)
      eliminated = tied.length === 1 ? tied[0] : breakElimination(tied, history)
      continuing.delete(eliminated)
    }

    rounds.push({ counts, exhausted, eliminated })

    if (activeTotal === 0 || roundWinner !== null) break
  }

  return { rounds, winner }
}
"}

