{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260923T221316Z/cell-kI4doV/src/format.js","content":"/**
 * Renders election results as the lines the CLI prints to standard output.
 */

/**
 * Formats one round's `round K: ...` line: continuing candidates ordered
 * by descending vote count and then ascending name, followed by the
 * exhausted-ballot total.
 */
export function formatRound(roundNumber, counts, exhausted) {
  const entries = [...counts.entries()].sort((a, b) => {
    if (b[1] !== a[1]) return b[1] - a[1]
    return a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0
  })
  const parts = entries.map(([name, votes]) => `${name}=${votes}`)
  parts.push(`exhausted=${exhausted}`)
  return `round ${roundNumber}: ${parts.join(' ')}`
}

/** Formats the final `winner <name>` or `no winner` line. */
export function formatOutcome(winner) {
  return winner === null ? 'no winner' : `winner ${winner}`
}
"}

